# Demo input
demo_input = [
    [2, 5, 4], [5, 3, 3], [4, 3, 4], [2, 7, 2],
    [7, 4, 1], [2, 1, 2], [3, 7, 0], [7, 6, 2],
    [0, 2, 3], [2, 4, 1], [4, 5, 5], [1, 5, 6],
    [6, 6, 3], [6, 0, 0], [6, 0, 6], [7, 4, 4],
    [4, 9, 1], [4, 1, 7]
]

demo_output = [
    [6, 6, 3],
    [6, 0, 0],
    [6, 0, 6]
]

# Check if output matches rows in input
for r in demo_output:
    for i, row in enumerate(demo_input):
        if row == r:
            print(f"Output row matches input row {i}: {r}")

# Maybe it's extracting a sub-grid? Check rows 12-14, columns 0,1,2
print("\nInput rows 12-14:")
for i in range(12, min(15, len(demo_input))):
    print(f"Row {i}: {demo_input[i]}")

# Next, find the pattern - maybe it's about unique 3-element subsequences in the first column
first_col = [row[0] for row in demo_input]
print("\nFirst column:", first_col)

# Group by first column
groups = []
for i in range(len(first_col)):
    if i == 0:
        groups.append((first_col[i], [i]))
    else:
        if first_col[i] == first_col[i-1]:
            groups[-1][1].append(i)
        else:
            groups.append((first_col[i], [i]))

print("\nGroups by first column:")
for col_val, indices in groups:
    print(f"  {col_val}: indices {indices}")

# Look at rows where first_col == 6
print("\nRows where first_col == 6:")
for i, row in enumerate(demo_input):
    if row[0] == 6:
        print(f"  Row {i}: {row}")

test_input = [
    [6, 4], [4, 1], [5, 2], [2, 4],
    [4, 4], [4, 4],
    [6, 0], [6, 0],
    [4, 3], [3, 3],
    [2, 6], [6, 6],
    [2, 2], [2, 6],
    [0, 0], [0, 0]
]

first_col = [row[0] for row in test_input]
print("First column:", first_col)

# Group consecutive identical values in first column
groups = []
for i in range(len(first_col)):
    if i == 0:
        groups.append((first_col[i], [i]))
    else:
        if first_col[i] == first_col[i-1]:
            groups[-1][1].append(i)
        else:
            groups.append((first_col[i], [i]))

print("\nGroups by consecutive first column:")
for col_val, indices in groups:
    print(f"  First column {col_val}: rows {indices} ({len(indices)} consecutive)")

# Find groups with exactly 3 rows
groups_of_3 = [(col_val, indices) for col_val, indices in groups if len(indices) == 3]
print("\nGroups of exactly 3 consecutive rows:")
for col_val, indices in groups_of_3:
    for i in indices:
        print(f"  Row {i}: {test_input[i]}")

